      "keystrokes": "cat > main.cpp << 'EOF'\n#include <bits/stdc++.h>\nusing namespace std;\n\nstatic const int MOD = 7340033;\n\nint MAXK;\nstruct Solver {\n    unordered_map<long long, vector<int>> memo;\n    vector<int> solve(long long s) {\n        auto it = memo.find(s);\n        if (it != memo.end()) return it->second;\n        vector<int> res(MAXK+1, 0);\n        // Base case: non-splittable square\n        if (s < 3 || (s % 2 == 0)) {\n            res[0] = 1;\n            memo[s] = res;\n            return res;\n        }\n        // s is odd and >= 3\n        long long t = (s - 1) / 2; // child size\n        vector<int> Ft = solve(t);\n        // Compute A = Ft * Ft (degree <= MAXK)\n        vector<int> A(MAXK+1, 0);\n        for (int i = 0; i <= MAXK; ++i) if (Ft[i]) {\n            long long ai = Ft[i];\n            int lim = MAXK - i;\n            for (int j = 0; j <= lim; ++j) if (Ft[j]) {\n                A[i + j] = (A[i + j] + (int)((ai * Ft[j]) % MOD)) % MOD;\n            }\n        }\n        // Compute B = A * A (degree <= MAXK)\n        vector<int> B(MAXK+1, 0);\n        for (int i = 0; i <= MAXK; ++i) if (A[i]) {\n            long long ai = A[i];\n            int lim = MAXK - i;\n            for (int j = 0; j <= lim; ++j) if (A[j]) {\n                B[i + j] = (B[i + j] + (int)((ai * A[j]) % MOD)) % MOD;\n            }\n        }\n        // F_s[0] = 1; F_s[k] = B[k-1] for k>=1\n        res[0] = 1;\n        for (int k = 1; k <= MAXK; ++k) {\n            res[k] = B[k-1] % MOD;\n        }\n        memo[s] = res;\n        return res;\n    }\n} ;\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int q;\n    if(!(cin >> q)) return 0;\n    vector<pair<long long,int>> queries(q);\n    MAXK = 0;\n    for(int i=0;i<q;i++){\n        long long n; int k; cin >> n >> k; queries[i] = {n, k}; if(k > MAXK) MAXK = k; }\n\n    Solver solver;\n    // Precompute answers for each query\n    for (int i = 0; i < q; ++i) {\n        long long n = queries[i].first; int k = queries[i].second;\n        vector<int> Fn = solver.solve(n);\n        cout << (k <= MAXK ? Fn[k] : 0) << \"\\n\";\n    }\n    return 0;\n}\n\nEOF\n\ng++ -std=c++17 -O2 -pipe -static -s -o main main.cpp\n\n./main << EOF\n8\n1 0\n1 1\n3 0\n3 1\n2 0\n2 1\n3 2\n7 2\nEOF"], 
