    cin.tie(nullptr);

    int T; if(!(cin >> T)) return 0;
    while(T--){
        int n, m; cin >> n >> m; // nodes 0..n, 0 is the door to summer
        int jStart, lStart; cin >> jStart >> lStart; // starting rooms
        vector<vector<pair<int,int>>> adj(n+1);
        for(int i = 0; i < m; ++i){
            int u, v; char t; cin >> u >> v >> t;
            int w = (t == 'N') ? 1 : 0; // N -> 1 (cost), L -> 0 (free)
            adj[u].push_back({v, w});
            adj[v].push_back({u, w});
        }
        const int INF = 1e9;
        vector<int> dist(n+1, INF);
        deque<int> dq;
        dist[lStart] = 0;
        dq.push_back(lStart);
        while(!dq.empty()){
            int u = dq.front(); dq.pop_front();
            for(auto &e: adj[u]){
                int v = e.first; int w = e.second;
                if(dist[u] + w < dist[v]){
                    dist[v] = dist[u] + w;
                    if(w == 0) dq.push_front(v);
                    else dq.push_back(v);
                }
            }
        }
        cout << dist[0] << "\n";
    }
    return 0;
}
